from __future__ import annotations

from dataclasses import dataclass


VALID_EFFECTS = {"Allow", "Deny"}
VALID_POLICY_TYPES = {"identity", "resource"}


def _require_text(value: str, field_name: str) -> None:
    if not value.strip():
        raise ValueError(f"{field_name} required")


@dataclass(frozen=True)
class PolicyStatement:
    sid: str
    effect: str
    actions: tuple[str, ...]
    resources: tuple[str, ...]
    policy_type: str
    principal_arns: tuple[str, ...] = ("*",)
    condition_keys: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        _require_text(self.sid, "sid")
        if self.effect not in VALID_EFFECTS:
            raise ValueError("effect must be Allow or Deny")
        if not self.actions:
            raise ValueError("actions required")
        if not self.resources:
            raise ValueError("resources required")
        if self.policy_type not in VALID_POLICY_TYPES:
            raise ValueError("policy_type must be identity or resource")
        for action in self.actions:
            _require_text(action, "action")
        for resource in self.resources:
            _require_text(resource, "resource")
        for principal in self.principal_arns:
            _require_text(principal, "principal_arn")
        for key in self.condition_keys:
            _require_text(key, "condition_key")

    def is_allow(self) -> bool:
        return self.effect == "Allow"

    def is_deny(self) -> bool:
        return self.effect == "Deny"


@dataclass(frozen=True)
class IamRequest:
    principal_arn: str
    action: str
    resource_arn: str
    context: dict[str, str] | None = None

    def __post_init__(self) -> None:
        _require_text(self.principal_arn, "principal_arn")
        _require_text(self.action, "action")
        _require_text(self.resource_arn, "resource_arn")
        for key, value in (self.context or {}).items():
            _require_text(key, "context key")
            _require_text(value, "context value")


@dataclass(frozen=True)
class MatchedStatement:
    sid: str
    effect: str
    policy_type: str
    action_pattern: str
    resource_pattern: str

    def __post_init__(self) -> None:
        _require_text(self.sid, "sid")
        if self.effect not in VALID_EFFECTS:
            raise ValueError("effect must be Allow or Deny")
        if self.policy_type not in VALID_POLICY_TYPES:
            raise ValueError("policy_type must be identity or resource")
        _require_text(self.action_pattern, "action_pattern")
        _require_text(self.resource_pattern, "resource_pattern")

    def summary(self) -> dict[str, str]:
        return {
            "sid": self.sid,
            "effect": self.effect,
            "policy_type": self.policy_type,
        }


@dataclass(frozen=True)
class SimulationTrace:
    request_action: str
    request_resource: str
    matched_allows: tuple[MatchedStatement, ...]
    matched_denies: tuple[MatchedStatement, ...]

    def __post_init__(self) -> None:
        _require_text(self.request_action, "request_action")
        _require_text(self.request_resource, "request_resource")

    def allow_sids(self) -> list[str]:
        return [match.sid for match in self.matched_allows]

    def deny_sids(self) -> list[str]:
        return [match.sid for match in self.matched_denies]


@dataclass(frozen=True)
class DeploymentGateDecision:
    decision: str
    allowed: bool
    reasons: tuple[str, ...]

    def __post_init__(self) -> None:
        if self.decision not in {"allowed", "explicit_deny", "implicit_deny"}:
            raise ValueError("unsupported decision")
        if self.allowed and self.decision != "allowed":
            raise ValueError("allowed flag must match decision")
        for reason in self.reasons:
            _require_text(reason, "reason")


def statement(
    sid: str,
    effect: str,
    actions: list[str],
    resources: list[str],
    policy_type: str,
    principal_arns: list[str] | None = None,
) -> PolicyStatement:
    return PolicyStatement(
        sid=sid,
        effect=effect,
        actions=tuple(actions),
        resources=tuple(resources),
        policy_type=policy_type,
        principal_arns=tuple(principal_arns or ["*"]),
    )


def request_context(**values: str) -> dict[str, str]:
    return dict(values)

