from __future__ import annotations

from iam_models import DeploymentGateDecision, IamRequest, MatchedStatement, PolicyStatement
from policy_matching import collect_matches, statement_matches, trace_summary


def _matches_any(value: str, patterns: tuple[str, ...]) -> bool:
    from policy_matching import matches_any

    return matches_any(value, patterns)


def _statement_matches(statement: PolicyStatement, request: IamRequest) -> bool:
    return statement_matches(statement, request)


def _statement_summary(statement: PolicyStatement | MatchedStatement) -> dict[str, str]:
    if isinstance(statement, MatchedStatement):
        return statement.summary()
    return {
        "sid": statement.sid,
        "effect": statement.effect,
        "policy_type": statement.policy_type,
    }


def explain_decision(
    decision: str,
    matched_allows: list[PolicyStatement] | list[MatchedStatement],
    matched_denies: list[PolicyStatement] | list[MatchedStatement],
) -> list[str]:
    if decision == "allowed":
        allow_sids = ", ".join(statement.sid for statement in matched_allows)
        return [f"allowed by {allow_sids}"]
    if decision == "explicit_deny":
        deny_sids = ", ".join(statement.sid for statement in matched_denies)
        return [f"explicit deny from {deny_sids}"]
    return ["no matching allow statement"]


def _final_decision(matched_allows: list[MatchedStatement], matched_denies: list[MatchedStatement]) -> DeploymentGateDecision:
    if matched_allows:
        reasons = tuple(explain_decision("allowed", matched_allows, matched_denies))
        return DeploymentGateDecision("allowed", True, reasons)
    if matched_denies:
        reasons = tuple(explain_decision("explicit_deny", matched_allows, matched_denies))
        return DeploymentGateDecision("explicit_deny", False, reasons)
    return DeploymentGateDecision("implicit_deny", False, ("no matching allow statement",))


def _result_payload(
    decision: DeploymentGateDecision,
    matched_allows: list[MatchedStatement],
    matched_denies: list[MatchedStatement],
    request: IamRequest,
) -> dict[str, object]:
    return {
        "decision": decision.decision,
        "allowed": decision.allowed,
        "matched_allows": [_statement_summary(statement) for statement in matched_allows],
        "matched_denies": [_statement_summary(statement) for statement in matched_denies],
        "reasons": list(decision.reasons),
        "trace": {
            "request_action": request.action,
            "request_resource": request.resource_arn,
            "matched_allow_count": len(matched_allows),
            "matched_deny_count": len(matched_denies),
        },
    }


def simulate_iam_request(
    request: IamRequest,
    statements: list[PolicyStatement],
) -> dict[str, object]:
    trace = collect_matches(request, statements)
    matched_allows = list(trace.matched_allows)
    matched_denies = list(trace.matched_denies)
    decision = _final_decision(matched_allows, matched_denies)
    result = _result_payload(decision, matched_allows, matched_denies, request)
    result["trace"].update(trace_summary(trace))  # type: ignore[index]
    return result


class IamPolicySimulator:
    def __init__(self, statements: list[PolicyStatement]) -> None:
        self.statements = list(statements)

    def simulate(self, request: IamRequest) -> dict[str, object]:
        return simulate_iam_request(request, self.statements)

    def preview_deployment(self, requests: list[IamRequest]) -> dict[str, object]:
        results = [self.simulate(request) for request in requests]
        blocked = [result for result in results if not result["allowed"]]
        return {
            "request_count": len(requests),
            "allowed_count": len(results) - len(blocked),
            "blocked_count": len(blocked),
            "results": results,
        }


def summarize_simulations(results: list[dict[str, object]]) -> dict[str, object]:
    return {
        "allowed_count": sum(1 for result in results if result["decision"] == "allowed"),
        "explicit_deny_count": sum(1 for result in results if result["decision"] == "explicit_deny"),
        "implicit_deny_count": sum(1 for result in results if result["decision"] == "implicit_deny"),
        "result_count": len(results),
    }

