from __future__ import annotations

from fnmatch import fnmatchcase

from iam_models import IamRequest, MatchedStatement, PolicyStatement, SimulationTrace


def matches_pattern(value: str, pattern: str) -> bool:
    return fnmatchcase(value.lower(), pattern.lower())


def matches_any(value: str, patterns: tuple[str, ...]) -> bool:
    return any(matches_pattern(value, pattern) for pattern in patterns)


def principal_matches(statement: PolicyStatement, request: IamRequest) -> bool:
    return matches_any(request.principal_arn, statement.principal_arns)


def conditions_match(statement: PolicyStatement, request: IamRequest) -> bool:
    if not statement.condition_keys:
        return True
    context = request.context or {}
    return all(key in context for key in statement.condition_keys)


def statement_matches(statement: PolicyStatement, request: IamRequest) -> bool:
    return (
        principal_matches(statement, request)
        and matches_any(request.action, statement.actions)
        and matches_any(request.resource_arn, statement.resources)
        and conditions_match(statement, request)
    )


def first_matching_pattern(value: str, patterns: tuple[str, ...]) -> str:
    for pattern in patterns:
        if matches_pattern(value, pattern):
            return pattern
    return patterns[0]


def matched_statement(statement: PolicyStatement, request: IamRequest) -> MatchedStatement:
    return MatchedStatement(
        sid=statement.sid,
        effect=statement.effect,
        policy_type=statement.policy_type,
        action_pattern=first_matching_pattern(request.action, statement.actions),
        resource_pattern=first_matching_pattern(request.resource_arn, statement.resources),
    )


def collect_matches(request: IamRequest, statements: list[PolicyStatement]) -> SimulationTrace:
    allows: list[MatchedStatement] = []
    denies: list[MatchedStatement] = []
    for statement in statements:
        if not statement_matches(statement, request):
            continue
        match = matched_statement(statement, request)
        if statement.is_allow():
            allows.append(match)
        else:
            denies.append(match)
    return SimulationTrace(
        request_action=request.action,
        request_resource=request.resource_arn,
        matched_allows=tuple(allows),
        matched_denies=tuple(denies),
    )


def trace_summary(trace: SimulationTrace) -> dict[str, object]:
    return {
        "request_action": trace.request_action,
        "request_resource": trace.request_resource,
        "allow_sids": trace.allow_sids(),
        "deny_sids": trace.deny_sids(),
        "matched_allow_count": len(trace.matched_allows),
        "matched_deny_count": len(trace.matched_denies),
    }


class PolicyMatcher:
    def __init__(self, statements: list[PolicyStatement]) -> None:
        self.statements = list(statements)

    def trace(self, request: IamRequest) -> SimulationTrace:
        return collect_matches(request, self.statements)

    def matching_sids(self, request: IamRequest) -> list[str]:
        trace = self.trace(request)
        return trace.allow_sids() + trace.deny_sids()

    def summary(self, request: IamRequest) -> dict[str, object]:
        return trace_summary(self.trace(request))

